params.command:
$ErrorActionPreference='Stop'
$runnerDir='C:\Users\Xxkan\actions-runner-heaven'
$work=Join-Path $runnerDir '_work\mhw-mods\mhw-mods'
$expected='132a12d470dd5f3c74813ebc596719bd9350ad92'
if(-not (Test-Path -LiteralPath (Join-Path $work '.git'))){ throw "Runner worktree missing: $work" }
$head=(& git -C $work rev-parse HEAD).Trim()
if($LASTEXITCODE -ne 0){ throw 'Could not resolve runner worktree HEAD.' }
if($head -ne $expected){ [pscustomobject]@{released=$false;reason='head_mismatch';expected=$expected;actual=$head}|ConvertTo-Json -Compress; exit 0 }
$listener=@(Get-CimInstance Win32_Process -ErrorAction SilentlyContinue | Where-Object { $_.Name -eq 'Runner.Listener.exe' -and $_.ExecutablePath -eq (Join-Path $runnerDir 'bin\Runner.Listener.exe') } | Select-Object -First 1)
if(-not $listener){ throw 'Configured Heaven Runner.Listener.exe is not alive.' }
$workers=@(Get-CimInstance Win32_Process -ErrorAction SilentlyContinue | Where-Object { $_.Name -eq 'Runner.Worker.exe' -and [int]$_.ParentProcessId -eq [int]$listener.ProcessId })
if($workers.Count -ne 1){ throw "Expected exactly one Runner.Worker child; found $($workers.Count)." }
$worker=$workers[0]
Stop-Process -Id $worker.ProcessId -Force
Start-Sleep -Seconds 2
if(Get-Process -Id $worker.ProcessId -ErrorAction SilentlyContinue){ throw 'Stale Runner.Worker still alive after forced termination.' }
[pscustomobject]@{released=$true;source=$head;listenerPid=$listener.ProcessId;workerPid=$worker.ProcessId;listenerStillAlive=[bool](Get-Process -Id $listener.ProcessId -ErrorAction SilentlyContinue)}|ConvertTo-Json -Compress
